import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.17 Save Workspace Template","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-17-save-workspace-template/spec.md","filePath":"feature/agency-workspace/3-4-17-save-workspace-template/spec.md"}'),n={name:"feature/agency-workspace/3-4-17-save-workspace-template/spec.md"};function i(r,e,c,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-4-17-save-workspace-template" tabindex="-1">3.4.17 Save Workspace Template <a class="header-anchor" href="#_3-4-17-save-workspace-template" aria-label="Permalink to &quot;3.4.17 Save Workspace Template&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.17</td></tr><tr><td>Feature</td><td>Save Workspace Template</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>Signed-in Agency member (no specific role restriction is applied)</td></tr><tr><td>Version</td><td>2.5 — 2026-09-25 — <code>WorkspaceTemplateServiceImpl</code> implemented (agency-scoped save/list/get/delete); stub warning resolved; <code>getTemplate</code> read-scope gap patched</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in Agency member saves the configuration of an existing Workspace as a template.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any signed-in member of the Agency; no specific role restriction is applied (unconfirmed whether one is intended — see BR-05).</li><li><strong>Purpose:</strong> Lets a member store a Workspace configuration as a reusable template so similar Workspaces can be created faster later.</li><li><strong>Interface:</strong> A &quot;Save as Template&quot; modal opened from Workspace settings (<code>detail.tsx</code>), plus a &quot;View all templates&quot; link to a separate templates list page (<code>templates.tsx</code>, routed at <code>/workspaces/templates</code>). ⚠ There is <strong>no separate detail route/page</strong> — the templates list page implements detail as an inline expand row (click the template name to toggle showing its <code>configSnapshot</code> inline); there is no dedicated URL for a single template&#39;s detail view.</li><li><strong>Data Processing:</strong> The system stores the template with the configuration snapshot captured from the Workspace, scoped automatically to the caller&#39;s Agency (resolved via the Agency the caller owns — same lookup as <code>WorkspaceServiceImpl.listMyWorkspaces</code>) and creator identity taken from the authenticated session.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Save Workspace Template Screen:</p><ul><li>A &quot;Save as Template&quot; button plus a &quot;View all templates&quot; link, both inside Workspace settings, shown only when <code>canManage</code> is true.</li><li>The &quot;Save as Template&quot; action opens a modal with a template name input; the configSnapshot is built automatically from the current Workspace&#39;s <code>timezone</code>, <code>defaultPlatforms</code>, and <code>reportFrequency</code> (JSON-stringified) — there is no free-form configSnapshot input and no <code>sourceWorkspaceId</code> picker in the UI (it is set silently to the current workspace&#39;s id).</li><li>The templates list page (<code>/workspaces/templates</code>) shows each template&#39;s name and creation date; clicking the name toggles an inline expand showing the raw <code>configSnapshot</code> text; a delete (trash) button removes it. There is no separate detail screen/route.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> name; configSnapshot (a JSON snapshot of the Workspace configuration).</li><li><strong>Input optional:</strong> sourceWorkspaceId (the Workspace the template was captured from).</li><li><strong>System data:</strong> The caller&#39;s authenticated identity; the Agency the caller belongs to; the creation timestamp.</li><li><strong>Output:</strong> The stored template — id, agencyId, name, sourceWorkspaceId, configSnapshot, createdBy, createdAt. The template list returns the same shape per entry, and the detail view returns one entry.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — the Agency and the creator of the template are taken automatically from the caller&#39;s session and never from the request payload; a template is scoped to the caller&#39;s Agency (<code>saveTemplate</code>/<code>listTemplates</code>/<code>deleteTemplate</code> all resolve <code>agencyId</code> via the Agency the caller owns).</li><li><strong>BR-02:</strong> Templates are a standalone resource, not nested inside an Agency or a Workspace; the available actions are create, list, delete, and inline-expand-to-view within the list (no separate detail route — see Screen Layout).</li><li><strong>BR-03:</strong> <code>name</code> or <code>configSnapshot</code> empty → 400 <code>VALIDATION_ERROR</code>.</li><li><strong>BR-04:</strong> Requesting or deleting a template that does not exist → 404 <code>NOT_FOUND</code>.</li><li><strong>BR-05:</strong> No specific role restriction is currently applied to these actions; whether access should be limited by Agency or role is still to be confirmed. ⚠ BA conflict (needs team decision): no dedicated BR-xx code in <code>Section5_Requirement_Appendix.md</code> covers this; needs a code assigned if a role restriction is intended.</li><li><strong>BR-06:</strong> A template is independent of its source Workspace — it remains available even after that Workspace is deleted.</li><li><strong>Implementation note:</strong> <code>getTemplate</code> and <code>deleteTemplate</code> both enforce the caller owns the template&#39;s Agency (403 <code>FORBIDDEN</code> otherwise) — <code>getTemplate</code> takes <code>currentUser</code> for this check as of this pass.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>name</code> must not be empty; otherwise 400 <code>VALIDATION_ERROR</code>, MSG02 (enforced via <code>@NotBlank</code> on <code>SaveWorkspaceTemplateRequest.name</code>).</li><li><code>configSnapshot</code> must not be empty; otherwise 400 <code>VALIDATION_ERROR</code>, MSG02 (enforced via <code>@NotBlank</code> on <code>SaveWorkspaceTemplateRequest.configSnapshot</code>).</li><li>The template must exist for delete/get; otherwise 404 <code>NOT_FOUND</code>, toast MSG38.</li><li>Getting or deleting a template belonging to a different Agency → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Member opens Workspace settings and clicks &quot;Save as Template&quot;, opening a modal.</li><li>Member fills in the template name; the configSnapshot is built automatically from the current Workspace&#39;s <code>timezone</code>/<code>defaultPlatforms</code>/<code>reportFrequency</code>, and <code>sourceWorkspaceId</code> is set to the current workspace&#39;s id — neither is a free-form input.</li><li>FE calls <code>POST /api/v1/workspace-templates</code>; System validates that the name and snapshot are not empty.</li><li>System resolves the caller&#39;s owned Agency and attaches <code>agencyId</code>/<code>createdBy</code> automatically (never from the request body).</li><li>System stores the template and returns it; FE shows a success toast and closes the modal. ⚠ Toast message key used is <code>workspace.settings.template.saveSuccess</code> (an i18n key), not literally MSG32 — MSG32 in the Section5 appendix is &quot;Updating workspace settings successfully&quot; / &quot;Settings saved.&quot;, a different, unrelated message; do not reuse MSG32 for template-save success without confirming a dedicated MSG code with BA.</li><li>Member can later open <code>/workspaces/templates</code> to list templates, expand one inline to view its configSnapshot, or delete it.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: <code>name</code> empty → 400 <code>VALIDATION_ERROR</code>, Display: MSG02. 3.a2: The user supplies a name and resubmits.</li><li>3.b1: <code>configSnapshot</code> empty → 400 <code>VALIDATION_ERROR</code>, Display: MSG02. 3.b2: The user captures the configuration and resubmits. (In the current UI this cannot happen — configSnapshot is always auto-built and non-empty.)</li><li>6.a1: Delete/get requested for a template that does not exist (BR-04) → 404 <code>NOT_FOUND</code>, toast MSG38. 6.a2: The user returns to the template list, which no longer shows that entry.</li><li>6.b1: The source Workspace is deleted after the template was saved (BR-06) → no error is raised. 6.b2: The template still exists and remains listable, because the stored snapshot does not depend on the source Workspace.</li><li>6.c1: Delete requested for a template belonging to another Agency → 403 <code>FORBIDDEN</code>. 6.c2: The user has no access; the template is unaffected.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>A template exists within the caller&#39;s Agency with the captured configuration snapshot.</li><li>The template remains available independently of the source Workspace.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Sharing templates across different Agencies (templates stay within one Agency).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
